contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test: deposit with a positive amount must succeed and increase address(c).balance by that amount
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 beforeContractBal = address(c).balance;

        bool reverted;
        c.deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractBal = address(c).balance;

        // General property: for any positive amount sent, deposit must not revert and contract balance increases exactly by amount
        assert(reverted == false && afterContractBal == beforeContractBal + amount);
    }

    receive() external payable {}
}

